import { createRoom } from '@/lib/game/lobby';
import { createLobbyStore } from '@/lib/game/lobby-store';
import { currentPlayer, unauthorized } from '@/lib/server-session';

/**
 * Opens a private room (spec §7.4).
 *
 * Takes no input at all: the host is the session, the game id is generated by the
 * database and the code is minted server-side.
 */
export async function POST(): Promise<Response> {
  const player = await currentPlayer();
  if (!player) {
    return unauthorized();
  }

  const room = await createRoom(createLobbyStore(), player);
  return Response.json(room, { status: 201 });
}
